examples.template:
Column {
    MonarchText(text = {{message}})
    MonarchAiFollowUpSuggestions(
        suggestions = listOf({{suggestions.0}}, {{suggestions.1}}, {{suggestions.2}}),
        onSelect = { sent = it },
    )
}

